insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('krevetki-v-chesnochnom-masle', 'main', false, null, 15, 240, 2, 'easy',
   '{"ru":"Креветки в чесночном масле","en":"Garlic butter shrimp"}'::jsonb,
   '{"ru":"Сочные креветки, обжаренные в сливочном масле с чесноком и петрушкой, с яркой ноткой лимона. Соус со дна сковороды — отдельное удовольствие, которое хочется собрать хлебом.","en":"Juicy shrimp seared in butter with garlic and parsley and a bright squeeze of lemon. The sauce left in the pan is a treat all its own — perfect for mopping up with bread."}'::jsonb,
   '{"ru":["Креветки — 400 г","Сливочное масло — 40 г","Чеснок — 3 зубчика","Лимон — ½ шт","Петрушка — небольшой пучок","Соль — по вкусу","Чёрный перец — по вкусу"],"en":["Shrimp — 400 g","Butter — 40 g","Garlic — 3 cloves","Lemon — ½","Parsley — a small bunch","Salt — to taste","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Обсушите креветки и обжарьте на разогретой сковороде по 1–2 минуты с каждой стороны.","Добавьте сливочное масло и измельчённый чеснок, прогрейте ещё 30 секунд.","Снимите с огня, посолите, поперчите и полейте лимонным соком.","Посыпьте рубленой петрушкой и сразу подавайте.","Совет: не пережаривайте — как только креветки стали розовыми и плотными, они готовы."],"en":["Pat the shrimp dry and sear on a hot pan 1–2 minutes per side.","Add the butter and minced garlic, warm for another 30 seconds.","Take off the heat, season and pour over the lemon juice.","Scatter with chopped parsley and serve at once.","Tip: don''t overcook — once the shrimp turn pink and firm, they''re done."]}'::jsonb,
   '{"ru":["ужин","креветки","чеснок","быстро"],"en":["dinner","shrimp","garlic","quick"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

