values
  ('krevetki-medovo-chili', 'main', false, null, 15, 260, 2, 'easy',
   '{"ru":"Креветки медово-чили","en":"Honey-chili shrimp"}'::jsonb,
   '{"ru":"Креветки в блестящей медово-чили глазури: сладкое встречается с острым, а соевый соус и лайм добавляют глубины. Ровно тот баланс, из-за которого тарелка пустеет первой.","en":"Shrimp in a glossy honey-chili glaze where sweet meets heat, rounded out by soy and lime. Exactly the balance that empties the plate first."}'::jsonb,
   '{"ru":["Креветки — 400 г","Мёд — 1 ст. л.","Соевый соус — 2 ст. л.","Сладкий чили-соус — 2 ст. л.","Чеснок — 2 зубчика","Сок лайма — 1 ст. л.","Зелёный лук — для подачи"],"en":["Shrimp — 400 g","Honey — 1 tbsp","Soy sauce — 2 tbsp","Sweet chili sauce — 2 tbsp","Garlic — 2 cloves","Lime juice — 1 tbsp","Spring onion — to serve"]}'::jsonb,
   '{"ru":["Смешайте мёд, соевый соус, сладкий чили, измельчённый чеснок и сок лайма.","Обжарьте креветки на сильном огне 2–3 минуты.","Влейте соус и прогрейте ещё минуту до густой блестящей глазури.","Подавайте, посыпав зелёным луком.","Совет: держите огонь сильным, чтобы соус карамелизовался, а не выпаривался."],"en":["Mix the honey, soy sauce, sweet chili, minced garlic and lime juice.","Sear the shrimp over high heat for 2–3 minutes.","Pour in the sauce and cook another minute to a thick, glossy glaze.","Serve scattered with spring onion.","Tip: keep the heat high so the sauce caramelises rather than just steams."]}'::jsonb,
   '{"ru":["ужин","креветки","острое","азиатское"],"en":["dinner","shrimp","spicy","asian"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
