  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('krevetki-v-slivochnom-souse', 'main', false, null, 20, 340, 2, 'easy',
   '{"ru":"Креветки в сливочном соусе","en":"Creamy garlic parmesan shrimp"}'::jsonb,
   '{"ru":"Нежные креветки в бархатистом сливочном соусе с чесноком и пармезаном. Тот случай, когда соус хочется собрать со сковороды хлебом до последней капли.","en":"Tender shrimp in a velvety cream sauce with garlic and parmesan. The kind of sauce you''ll want to wipe out of the pan with bread to the last drop."}'::jsonb,
   '{"ru":["Креветки — 400 г","Сливки 20% — 200 мл","Пармезан — 50 г","Чеснок — 2 зубчика","Сливочное масло — 20 г","Соль — по вкусу","Чёрный перец — по вкусу"],"en":["Shrimp — 400 g","Cream 20% — 200 ml","Parmesan — 50 g","Garlic — 2 cloves","Butter — 20 g","Salt — to taste","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Обжарьте креветки на масле 1–2 минуты и уберите со сковороды.","В той же сковороде прогрейте чеснок, влейте сливки и добавьте тёртый пармезан.","Прогрейте соус до загустения, посолите и поперчите.","Верните креветки в соус ещё на 1 минуту и подавайте.","Совет: снимайте креветки заранее, чтобы они не стали резиновыми, пока густеет соус."],"en":["Sear the shrimp in butter for 1–2 minutes and remove from the pan.","In the same pan warm the garlic, pour in the cream and add grated parmesan.","Simmer the sauce until it thickens, then season.","Return the shrimp to the sauce for 1 more minute and serve.","Tip: pull the shrimp early so they don''t turn rubbery while the sauce reduces."]}'::jsonb,
   '{"ru":["ужин","креветки","сливки","пармезан"],"en":["dinner","shrimp","cream","parmesan"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('hrustyaschie-krevetki', 'snack', false, null, 25, 320, 3, 'medium',
   '{"ru":"Хрустящие креветки в панировке","en":"Crispy breaded shrimp"}'::jsonb,
   '{"ru":"Креветки в золотистой панировке из сухарей с паприкой — хрустящие снаружи и сочные внутри. Идеальная закуска под белый соус: макаешь — и пропал.","en":"Shrimp in a golden paprika-breadcrumb coating — crunchy outside, juicy within. The ideal dipping snack: one dunk in the white sauce and you''re hooked."}'::jsonb,
   '{"ru":["Креветки — 400 г","Яйцо — 1 шт","Панировочные сухари — 80 г","Мука — 3 ст. л.","Паприка — 1 ч. л.","Соль — по вкусу","Масло для жарки — по необходимости"],"en":["Shrimp — 400 g","Egg — 1","Breadcrumbs — 80 g","Flour — 3 tbsp","Paprika — 1 tsp","Salt — to taste","Oil for frying — as needed"]}'::jsonb,
   '{"ru":["Смешайте сухари с паприкой и солью.","Обваляйте креветки в муке, затем во взбитом яйце и в сухарях.","Обжарьте во фритюре или на сковороде до золотистой корочки — либо запеките до хруста.","Обсушите на бумажном полотенце и подавайте с белым соусом.","Совет: для более лёгкого варианта запеките креветки в духовке при 200 °C, сбрызнув маслом."],"en":["Mix the breadcrumbs with paprika and salt.","Coat the shrimp in flour, then beaten egg, then breadcrumbs.","Deep-fry or pan-fry until golden — or bake until crisp.","Drain on paper towel and serve with a white dipping sauce.","Tip: for a lighter version, bake at 200 °C with a spritz of oil."]}'::jsonb,
   '{"ru":["закуска","креветки","хрустящее","фритюр"],"en":["snack","shrimp","crispy","fried"]}'::jsonb)
on conflict (slug) do update set
