insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kokosovoe-karri-s-krevetkami', 'main', false, null, 25, 360, 3, 'easy',
   '{"ru":"Кокосовое карри с креветками","en":"Coconut shrimp curry"}'::jsonb,
   '{"ru":"Креветки в нежном кокосовом соусе с карри, имбирём и лаймом — пряное, ароматное и совсем не сложное. Подавайте с рассыпчатым рисом.","en":"Shrimp in a gentle coconut sauce with curry, ginger and lime — spiced, fragrant and genuinely easy. Serve with fluffy rice."}'::jsonb,
   '{"ru":["Креветки — 400 г","Кокосовое молоко — 250 мл","Карри — 1 ч. л.","Чеснок — 2 зубчика","Имбирь — 1 ч. л.","Сок лайма — по вкусу","Кинза — для подачи","Рис — для подачи"],"en":["Shrimp — 400 g","Coconut milk — 250 ml","Curry powder — 1 tsp","Garlic — 2 cloves","Ginger — 1 tsp","Lime juice — to taste","Cilantro — to serve","Rice — to serve"]}'::jsonb,
   '{"ru":["Прогрейте на сковороде измельчённый чеснок, имбирь и карри до аромата.","Влейте кокосовое молоко и доведите до лёгкого кипения.","Добавьте креветки и готовьте 3–4 минуты до готовности.","В конце влейте сок лайма, посыпьте кинзой и подавайте с рисом.","Совет: не кипятите соус слишком долго — креветки станут жёсткими."],"en":["Warm the minced garlic, ginger and curry in a pan until fragrant.","Pour in the coconut milk and bring to a gentle simmer.","Add the shrimp and cook 3–4 minutes until done.","Finish with lime juice, scatter cilantro and serve with rice.","Tip: don''t over-simmer the sauce or the shrimp turn tough."]}'::jsonb,
   '{"ru":["ужин","креветки","карри","кокос"],"en":["dinner","shrimp","curry","coconut"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
