insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('krevetki-teriyaki', 'main', false, null, 15, 280, 2, 'easy',
   '{"ru":"Креветки терияки","en":"Teriyaki shrimp"}'::jsonb,
   '{"ru":"Креветки в блестящей глазури терияки из соевого соуса, мёда, чеснока и имбиря, посыпанные кунжутом. Подайте с рисом — и ужин готов за 15 минут.","en":"Shrimp in a shiny teriyaki glaze of soy, honey, garlic and ginger, finished with sesame. Serve over rice and dinner is done in 15 minutes."}'::jsonb,
   '{"ru":["Креветки — 400 г","Соевый соус — 3 ст. л.","Мёд — 1 ст. л.","Чеснок — 2 зубчика","Имбирь — ½ ч. л.","Кунжут — для подачи","Зелёный лук — для подачи","Рис — для подачи"],"en":["Shrimp — 400 g","Soy sauce — 3 tbsp","Honey — 1 tbsp","Garlic — 2 cloves","Ginger — ½ tsp","Sesame seeds — to serve","Spring onion — to serve","Rice — to serve"]}'::jsonb,
   '{"ru":["Смешайте соевый соус, мёд, измельчённый чеснок и имбирь.","Обжарьте креветки на сильном огне 2 минуты.","Влейте соус и готовьте ещё минуту до красивой блестящей глазури.","Посыпьте кунжутом и зелёным луком, подавайте с рисом.","Совет: соус загустеет быстро — снимайте с огня, как только он станет глянцевым."],"en":["Mix the soy sauce, honey, minced garlic and ginger.","Sear the shrimp over high heat for 2 minutes.","Pour in the sauce and cook another minute to a glossy glaze.","Scatter with sesame and spring onion and serve with rice.","Tip: the sauce thickens fast — pull it off the heat as soon as it turns glossy."]}'::jsonb,
   '{"ru":["ужин","креветки","терияки","азиатское"],"en":["dinner","shrimp","teriyaki","asian"]}'::jsonb)
