insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('limonno-perechnye-krevetki', 'main', false, null, 10, 220, 2, 'easy',
   '{"ru":"Лимонно-перечные креветки","en":"Lemon pepper shrimp"}'::jsonb,
   '{"ru":"Креветки, обжаренные до румяности со сливочным маслом, чесноком, свежемолотым перцем и цедрой лимона. Свежо, сочно и готово за 10 минут.","en":"Shrimp seared golden with butter, garlic, cracked pepper and lemon zest. Fresh, juicy and ready in 10 minutes."}'::jsonb,
   '{"ru":["Креветки — 400 г","Сливочное масло — 30 г","Лимон — 1 шт","Чеснок — 2 зубчика","Чёрный перец — по вкусу","Соль — по вкусу"],"en":["Shrimp — 400 g","Butter — 30 g","Lemon — 1","Garlic — 2 cloves","Black pepper — to taste","Salt — to taste"]}'::jsonb,
   '{"ru":["Обжарьте креветки на сухой разогретой сковороде до румяности.","Добавьте сливочное масло и измельчённый чеснок.","Всыпьте свежемолотый чёрный перец, добавьте цедру и сок лимона.","Посолите, прогрейте ещё несколько секунд и подавайте.","Совет: перчите свежемолотым перцем прямо в сковороду — аромат будет ярче."],"en":["Sear the shrimp on a hot dry pan until golden.","Add the butter and minced garlic.","Add freshly cracked black pepper, then lemon zest and juice.","Season with salt, warm a few more seconds and serve.","Tip: grind the pepper fresh straight into the pan for a brighter aroma."]}'::jsonb,
   '{"ru":["ужин","креветки","лимон","быстро"],"en":["dinner","shrimp","lemon","quick"]}'::jsonb)
