insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('pasta-s-krevetkami', 'main', false, null, 25, 520, 2, 'easy',
   '{"ru":"Паста с креветками в сливочном соусе","en":"Creamy shrimp pasta"}'::jsonb,
   '{"ru":"Спагетти с креветками в сливочном соусе с чесноком и пармезаном — тот самый ужин «как в ресторане», который легко приготовить дома за 25 минут.","en":"Spaghetti and shrimp in a creamy garlic-parmesan sauce — that restaurant-style dinner you can make at home in 25 minutes."}'::jsonb,
   '{"ru":["Спагетти — 200 г","Креветки — 300 г","Сливки — 150 мл","Пармезан — 40 г","Чеснок — 2 зубчика","Сливочное масло — 20 г","Соль — по вкусу","Чёрный перец — по вкусу"],"en":["Spaghetti — 200 g","Shrimp — 300 g","Cream — 150 ml","Parmesan — 40 g","Garlic — 2 cloves","Butter — 20 g","Salt — to taste","Black pepper — to taste"]}'::jsonb,
   '{"ru":["Отварите спагетти до состояния аль денте и слейте воду, сохранив немного отвара.","Обжарьте креветки с чесноком на сливочном масле 1–2 минуты.","Влейте сливки и добавьте тёртый пармезан, прогрейте до загустения.","Соедините с пастой, при необходимости добавьте немного отвара и прогрейте 1 минуту.","Совет: ложка воды от пасты сделает соус шелковистым и обволакивающим."],"en":["Boil the spaghetti al dente and drain, keeping a little cooking water.","Sear the shrimp with garlic in butter for 1–2 minutes.","Pour in the cream and add grated parmesan, simmer until thickened.","Toss with the pasta, loosen with a splash of the water and warm for 1 minute.","Tip: a spoon of pasta water makes the sauce silky and clingy."]}'::jsonb,
   '{"ru":["ужин","креветки","паста","сливки"],"en":["dinner","shrimp","pasta","cream"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
